SELECT define_provision($q$TCC_CITY_PLAN_2014@2025-12-08$q$, $q$QDC relationship: Table 1.6.1$q$, 'APPLICATION', $q$Character Residential Zone || Building assessment provisions – regulated building work in accordance with sections 32 and 33 of the Building Act 1975 | Character Residential Zone Editor’s note—This code contains alternative provisions for dwelling houses and dual occupancies to those set out in the Queensland Development Code (MP 1.1, MP 1.2 and MP1.3) , for the purposes of section 33 of the Building Act 1975 . | Sections 32 and 33 BA$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://tccplanningscheme.z8.web.core.windows.net/current/Part%201%20About%20the%20planning%20scheme.pdf$q$, NULL, NULL);
