SELECT define_provision($q$TCC_CITY_PLAN_2014@2025-12-08$q$, $q$QDC relationship: 1.7.2$q$, 'APPLICATION', $q$For the purpose of Schedule 9, of the Planning Regulation, building work for a building or structure which is a single detached class 1(a)(i) building, class 1(a)(ii) building comprising not more than 2 attached dwellings or a class 10 building or structure in a locality identified in Table 1.7.2 that does not comply with the relevant QDC acceptable solutions or the acceptable outcomes in the codes identified in Table 1.7.2, is declared to: (a) have an extremely adverse effect on the amenity or likely amenity of the locality; or (b) be in extreme conflict with the character of the locality$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://tccplanningscheme.z8.web.core.windows.net/current/Part%201%20About%20the%20planning%20scheme.pdf$q$, NULL, NULL);
SELECT define_provision($q$TCC_CITY_PLAN_2014@2025-12-08$q$, $q$def setback$q$, 'DEFINITION', $q$Setback, for a building or structure, means the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2 Table SC1.2.2$q$, NULL, $q$https://tccplanningscheme.z8.web.core.windows.net/current/Schedule%201%20Definitions.pdf$q$, NULL, NULL);
SELECT define_provision($q$TCC_CITY_PLAN_2014@2025-12-08$q$, $q$def boundary clearance$q$, 'DEFINITION', $q$Boundary clearance means the distance between a building or structure on premises and the boundary of the premises, measured from the part of the building or structure that is closest to the boundary, other than a part that is— (a) an architectural or ornamental attachment; or (b) a rainwater fitting. Examples— 1. If the fascia of a building is the part of the building that is closest to the boundary, the boundary clearance is the distance between the outside of the fascia and the boundary. 2. If a point on the roof of a building is the part of the building that is closest to the boundary, the boundary clearance is the distance between that point on the roof and the boundary.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2 Table SC1.2.2$q$, NULL, $q$https://tccplanningscheme.z8.web.core.windows.net/current/Schedule%201%20Definitions.pdf$q$, NULL, NULL);
SELECT define_provision($q$TCC_CITY_PLAN_2014@2025-12-08$q$, $q$def domestic outbuilding$q$, 'DEFINITION', $q$Domestic outbuilding means a non-habitable class 10a building that is— (a) a shed, garage or carport; and (b) ancillary to a residential use carried out on the premises where the building is.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$SC1.2 Table SC1.2.2$q$, NULL, $q$https://tccplanningscheme.z8.web.core.windows.net/current/Schedule%201%20Definitions.pdf$q$, NULL, NULL);
