SELECT define_provision($q$TCC_CITY_PLAN_2014@2025-12-08$q$, $q$LOA Table 5.7.1 Class 10 building work / Character residential zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Assessable development - Code assessment | If: (a) involving partial demolition, external alteration, extension (including minor building work and the construction of a class 10a building (as defined by the Building Code of Australia)), to a contributing character building where all or part of the work is in front of or within a depth of 3m from the facade facing any street; or ... (d) involving construction of a class 10a building (as defined by the Building Code of Australia) on the site of a non-contributing property, where all or part of the work is in front of, or within a depth of 3m from the main building façade facing any street; or ... | Character residential zone code || Accepted development | ... Any other building work not listed in this table.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://tccplanningscheme.z8.web.core.windows.net/current/Part%205%20Tables%20of%20assessment.pdf$q$, $q$Level: Code assessment (Character residential zone code) in listed cases; otherwise accepted. Conditions: class 10a near street facade$q$, NULL);
